// Construction du texte pour scoring sémantique + conservation des métadonnées essentielles
try {
  const { snippet = {}, id, contentDetails = {} } = $json;
  const { title = "", description = "", tags = [], channelTitle = "", publishedAt = "", channelId = "" } = snippet;

  // Validation: s'assurer que nous avons un ID
  if (!id) {
    return {
      json: {
        video_id: null,
        text_for_scoring: "",
        error: "missing_video_id"
      }
    };
  }

  // --- Extraction de la durée (format ISO 8601) ---
  const duration = contentDetails?.duration || null;

  // --- Extraction du nom du channel ---
  const channel = channelTitle || null;

  // --- Extraction de la date de publication ---
  const publishedDate = publishedAt || null;

  // --- Rognage ultra-simple du descriptif ---
  const MAX_WORDS = 100; // mets 150 si tu veux
  const croppedDescription = description
    .split(/\s+/)
    .slice(0, MAX_WORDS)
    .join(" ")
    .trim();

  // Construction du texte de scoring
  const textForScoring = `
TITLE:
${title}
DESCRIPTION:
${croppedDescription}
TAGS:
${Array.isArray(tags) ? tags.join(", ") : ""}
  `.trim();

  // Retourner les métadonnées essentielles
  return {
    json: {
      video_id: id,
      text_for_scoring: textForScoring,

      // Métadonnées supplémentaires
      title: title,
      duration: duration,
      channel: channel,
      channel_id: channelId || null,
      published_at: publishedDate
    }
  };

} catch (error) {
  console.error('Metadata extraction error:', error.message, 'video:', $json.id);
  return {
    json: {
      video_id: $json.id ?? null,
      text_for_scoring: "",
      error: error.message
    }
  };
}

