/**
 * Parse date relative en objet Date
 */
function parseRelativeDate(dateString) {
  if (!dateString || typeof dateString !== 'string') return null;

  const normalized = dateString.trim().toLowerCase();
  const now = new Date();

  const patterns = [
    { regex: /(\d+)\s*years?\s*ago/, unit: 'years' },
    { regex: /(\d+)\s*months?\s*ago/, unit: 'months' },
    { regex: /(\d+)\s*weeks?\s*ago/, unit: 'weeks' },
    { regex: /(\d+)\s*days?\s*ago/, unit: 'days' },
    { regex: /(\d+)\s*hours?\s*ago/, unit: 'hours' },
    { regex: /(\d+)\s*minutes?\s*ago/, unit: 'minutes' }
  ];

  for (const pattern of patterns) {
    const match = normalized.match(pattern.regex);
    if (match) {
      const value = parseInt(match[1]);
      const date = new Date(now);

      switch (pattern.unit) {
        case 'years':
          date.setFullYear(date.getFullYear() - value);
          break;
        case 'months':
          date.setMonth(date.getMonth() - value);
          break;
        case 'weeks':
          date.setDate(date.getDate() - (value * 7));
          break;
        case 'days':
          date.setDate(date.getDate() - value);
          break;
        case 'hours':
          date.setHours(date.getHours() - value);
          break;
        case 'minutes':
          date.setMinutes(date.getMinutes() - value);
          break;
      }

      return date;
    }
  }

  return null;
}

/**
 * Vérifie si une date est dans la plage
 */
function isInDateRange(dateString) {
  const videoDate = parseRelativeDate(dateString);
  if (!videoDate) return false;
  return videoDate >= startDate && videoDate <= endDate;
}

