    : null;

  // Statistiques des scores
  const scores = videos.map(v => v.score).filter(s => typeof s === 'number');
  const avgScore = scores.length > 0
    ? parseFloat((scores.reduce((a, b) => a + b, 0) / scores.length).toFixed(3))
    : 0;
  const minScore = scores.length > 0 ? parseFloat(Math.min(...scores).toFixed(3)) : 0;
  const maxScore = scores.length > 0 ? parseFloat(Math.max(...scores).toFixed(3)) : 0;

  // Distribution des scores par tranches
  const scoreDistribution = {
    '0.0-0.2': 0,
    '0.2-0.4': 0,
    '0.4-0.6': 0,
    '0.6-0.8': 0,
    '0.8-1.0': 0
  };

  for (const score of scores) {
