    else if (score < 0.4) scoreDistribution['0.2-0.4']++;
    else if (score < 0.6) scoreDistribution['0.4-0.6']++;
    else if (score < 0.8) scoreDistribution['0.6-0.8']++;
    else scoreDistribution['0.8-1.0']++;
  }

